function auth(req, res, next) { return req.session && req.session.isLoggedIn ? next() : res.redirect('/login'); }
function adminAuth(req, res, next) { if (!req.session || !req.session.isLoggedIn) return res.redirect('/login'); if (req.session.userRole === 'admin' || req.session.userRole === 'sub_admin') return next(); return res.redirect('/student/dashboard'); }

async function checkDeviceSession(req, res, next) {
    if (!req.session || !req.session.isLoggedIn) return next();
    if (req.session.userRole !== 'student') return next();
    if (!dbConnected) return next();
    try { const [user] = await db.query(`SELECT session_token, is_active FROM users WHERE id=$1`, { bind: [req.session.userId] }); if (user.length === 0) { req.session.destroy(); return res.redirect('/login?msg=account_deleted'); } if (!user[0].is_active) { req.session.destroy(); return res.redirect('/login?msg=account_deactivated'); } if (user[0].session_token && req.session.deviceToken !== user[0].session_token) { req.session.destroy(); return res.redirect('/login?msg=another_device'); } } catch(e) {}
    next();
}

// Email Helper
async function sendEmailNotification(to, subject, html) {
    if (!process.env.EMAIL_USER || !process.env.EMAIL_PASS) { console.log('⚠️ Email not configured'); return false; }
    try {
        const nodemailer = require('nodemailer');
        const transporter = nodemailer.createTransport({ host: process.env.EMAIL_HOST || 'smtp.gmail.com', port: parseInt(process.env.EMAIL_PORT || '465'), secure: true, auth: { user: process.env.EMAIL_USER, pass: process.env.EMAIL_PASS } });
        await transporter.sendMail({ from: `"${process.env.EMAIL_FROM || T.name}" <${process.env.EMAIL_USER}>`, to, subject, html });
        console.log('✅ Email sent to:', to); return true;
    } catch(e) { console.error('❌ Email:', e.message); return false; }
}

