app.post('/login', async (req, res) => { try { const { username, password } = req.body; if(!dbConnected) return res.send(`<script>alert('DB not connected!');window.location.href='/login'</script>`); const [users]=await db.query(`SELECT * FROM users WHERE email=$1 OR username=$1 OR student_id=$1`,{bind:[username]}); if(users.length===0) return res.send(`<script>alert('User not found!');window.location.href='/login'</script>`); const user=users[0]; if(!user.is_active) return res.send(`<script>alert('Account deactivated!');window.location.href='/login'</script>`); const valid=await bcrypt.compare(password,user.password); if(!valid) return res.send(`<script>alert('Wrong password!');window.location.href='/login'</script>`); if (user.role === 'student') { const newToken = crypto.randomBytes(32).toString('hex'); await db.query(`UPDATE users SET session_token=$1, session_device=$2 WHERE id=$3`, { bind: [newToken, (req.headers['user-agent']||'Unknown').substring(0,200), user.id] }); req.session.deviceToken = newToken; } await db.query(`UPDATE users SET last_login_at=NOW() WHERE id=$1`,{bind:[user.id]}); req.session.isLoggedIn=true; req.session.userId=user.id; req.session.studentId=user.student_id; req.session.userName=user.full_name; req.session.userMobile=user.mobile_number; req.session.userRole=user.role; if(user.role==='admin'||user.role==='sub_admin'){ req.session.isAdminLoggedIn=true; return res.redirect('/admin/dashboard'); } return res.redirect('/student/dashboard'); } catch(e){res.send(`<script>alert('Login failed!');window.location.href='/login'</script>`);} });

