app.get('/student/courses', auth, checkDeviceSession, async (req, res) => { let courses=[]; if(dbConnected){try{const [rows]=await db.query(`SELECT * FROM courses WHERE status='published' ORDER BY is_paper,created_at DESC`); courses=rows;}catch(e){}} let cc=''; courses.forEach(c=>{cc+=`<div class="course-card"><h3>📚 ${c.title} ${c.is_paper?'📝':''}</h3><p>${c.description||''}</p>${c.paper_url?`<a href="/uploads/${c.paper_url}" class="btn" style="background:#ff9800;margin-right:5px">📄 Paper</a>`:''}${c.answer_url?`<a href="/uploads/${c.answer_url}" class="btn" style="background:#4caf50">✅ Answer</a>`:''}<a href="/student/courses/${c.id}/lessons" class="btn">📖 Lessons</a></div>`;}); if(!cc) cc='<p style="text-align:center;padding:30px;">No courses.</p>'; res.send(`<!DOCTYPE html><html><head><title>Courses</title><meta charset="UTF-8"><style>*{margin:0;padding:0}body{font-family:'Segoe UI',Arial,sans-serif;background:#f0f2f5}.header{background:linear-gradient(135deg,#1a237e,#283593);color:white;padding:15px 25px;display:flex;justify-content:space-between;align-items:center}.logout{background:#dc3545;color:white;padding:8px 18px;border-radius:5px;text-decoration:none}.container{max-width:900px;margin:25px auto;padding:0 20px}h2{color:#1a237e}.course-card{background:white;padding:20px;border-radius:12px;box-shadow:0 3px 10px rgba(0,0,0,0.08);margin-bottom:15px}.btn{display:inline-block;padding:10px 22px;color:white;text-decoration:none;border-radius:8px;font-weight:bold;margin-top:5px;background:#1a237e}</style></head><body><div class="header"><h1>👨‍🎓 ${req.session.userName}</h1><a href="/logout" class="logout">🚪 Logout</a></div><div class="container"><h2>📚 Courses</h2>${cc}</div></body></html>`); });
